const p = $('Params').first().json;
const r = $input.first().json; const cur = {};
for (const k of ((r.body && r.body.keys) || [])) { cur[k.key_id] = k; }
const out = []; const report = [];
for (const k of p.keys) {
  const c = cur[k.key_id];
  if (!c || c.is_archived) { report.push({ key_id: k.key_id, skip: 'missing or archived' }); continue; }
  const have = c.tags || [];
  const add = k.tags.filter(function (t) { return have.indexOf(t) < 0; });
  const item = { key_id: k.key_id };
  if (add.length) { item.tags = add; item.merge_tags = true; }
  const descEmpty = !c.description || !String(c.description).trim();
  if (descEmpty && k.description) { item.description = k.description; }
  report.push({ key_id: k.key_id, tags_added: add, description: descEmpty ? 'added' : 'existing - kept', had_screenshots: (c.screenshots || []).length });
  if (item.tags || item.description) { out.push(item); }
}
const body = { keys: p.only_first ? out.slice(0, 1) : out };
return [{ json: { body: body, count: body.keys.length, report: report } }];

const p = $('Params').first().json;
if (p.only_first) { return []; }
const r = $('Get Keys').first().json; const has = {};
for (const k of ((r.body && r.body.keys) || [])) { has[k.key_id] = (k.screenshots || []).length; }
const out = [];
for (const s of p.shots) {
  const ids = s.key_ids.filter(function (id) { return !has[id]; });
  if (ids.length) { out.push({ json: { att: s.att, title: s.title, description: s.description, key_ids: ids, tag: s.title.split(' ')[0] } }); }
}
return out;

const src = $('Shots').all(); const items = $input.all(); const out = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const s = src[i].json;
  out.push({ json: { body: { screenshots: [{ data: 'data:image/png;base64,' + buf.toString('base64'), title: s.title, description: s.description, ocr: false, key_ids: s.key_ids, tags: [s.tag] }] } } });
}
return out;
